//! The generated files: a Rust module and a coverage file for each face at
//! each size, `mod.rs` naming them all, and `manifest.toml`, which says
//! what they were made from.
//!
//! The Rust is plain ASCII, in a fixed order, with no time, path or host in
//! it: the same inputs give the same bytes.

use std::fmt::Write as _;

use crate::raster::{FaceAtlas, SizeAtlas};
use crate::spec::{Face, PinnedFile, Spec};
use crate::{Atlases, Error};

/// What `swash` version made the coverage: a new one can change it.
const RASTERISER: &str = "swash 0.2.10";
/// How every atlas is made.
const HOW: &str = "unhinted, 8-bit coverage, metrics in 1/64 pixel, GPOS pair kerning in font units \
                   scaled at each size, no ligatures";

/// A character as a Rust character literal, in ASCII.
#[must_use]
pub fn char_literal(ch: char) -> String {
    match ch {
        '\'' => "'\\''".into(),
        '\\' => "'\\\\'".into(),
        ' '..='~' => format!("'{ch}'"),
        _ => format!("'\\u{{{:x}}}'", u32::from(ch)),
    }
}

/// Text as a Rust string literal, in ASCII.
#[must_use]
pub fn rust_string(text: &str) -> String {
    let mut out = String::from("\"");
    for ch in text.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            ' '..='~' => out.push(ch),
            _ => {
                let _ = write!(out, "\\u{{{:x}}}", u32::from(ch));
            }
        }
    }
    out.push('"');
    out
}

/// Text as a TOML basic string, in ASCII.
#[must_use]
pub fn toml_string(text: &str) -> String {
    let mut out = String::from("\"");
    for ch in text.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            ' '..='~' => out.push(ch),
            _ if u32::from(ch) <= 0xFFFF => {
                let _ = write!(out, "\\u{:04X}", u32::from(ch));
            }
            _ => {
                let _ = write!(out, "\\U{:08X}", u32::from(ch));
            }
        }
    }
    out.push('"');
    out
}

/// A licence's name, for the notice.
fn licence_name(licence: &str) -> String {
    if licence == "OFL-1.1" {
        "the SIL Open Font License, Version 1.1 (OFL-1.1)".into()
    } else {
        licence.into()
    }
}

/// The comment every generated file opens with.
fn header(comment: &str, spec: &Spec, fonts: &[(&Face, &PinnedFile)]) -> String {
    let family = &spec.family;
    let mut text = format!(
        "{comment} Generated by tools/glyph-atlas from {} - do not edit: `make atlases` writes it again.\n{comment}\n",
        crate::SPEC_FILE
    );
    // Each font file once, though several faces may be made from it.
    for (index, (face, file)) in fonts.iter().enumerate() {
        if fonts
            .iter()
            .take(index)
            .any(|(_, earlier)| earlier.path == file.path)
        {
            continue;
        }
        let _ = writeln!(
            text,
            "{comment} Made from {} {}, {}: {},\n{comment} sha256 {}.",
            family.name, file.version, face.style, file.path, file.sha256
        );
    }
    let _ = write!(
        text,
        "{comment} {}\n{comment} Licensed under {}:\n\
         {comment} a Modified Version of the font, made by NoWayOS's glyph atlas tool (tools/glyph-atlas).\n\
         {comment} The licence is {} in this crate's folder.\n",
        family.copyright,
        licence_name(&family.licence),
        family.licence_file
    );
    text
}

/// The notice every copy of the atlases carries, on one line: the
/// copyright line and the licence, as the OFL's own header gives them.
fn notice(spec: &Spec) -> String {
    let family = &spec.family;
    let stop = if family.copyright.ends_with('.') {
        ""
    } else {
        "."
    };
    if family.licence == "OFL-1.1" {
        format!(
            "{}{stop} This Font Software is licensed under the SIL Open Font License, Version 1.1.",
            family.copyright
        )
    } else {
        format!(
            "{}{stop} Licensed under {}.",
            family.copyright, family.licence
        )
    }
}

/// The atlas's module name: `regular_24`.
fn module(face: &Face, size: u16) -> String {
    format!("{}_{size}", face.name)
}

/// The face's kerning module's name: `regular_kerning`.
fn kerning_module(face: &Face) -> String {
    format!("{}_kerning", face.name)
}

/// The generated files for `faces`, each with its pinned file and its
/// atlases, size by size, and its kerning, shared by its sizes.
pub fn files(spec: &Spec, faces: &[(&Face, &PinnedFile, FaceAtlas)]) -> Result<Atlases, Error> {
    let fonts: Vec<(&Face, &PinnedFile)> =
        faces.iter().map(|(face, file, _)| (*face, *file)).collect();
    let mut files = Vec::new();
    let mut statics = Vec::new();
    let mut kerning_modules = Vec::new();
    let mut atlas_entries = String::new();
    let mut coverage_bytes = 0_usize;
    let mut glyph_count = Vec::new();
    for ((face, file, atlas), (chars, ranges)) in faces.iter().zip(&spec.face_sets) {
        let kerning = kerning_module(face);
        files.push((
            format!("{kerning}.rs"),
            kerning_rs(spec, face, file, atlas, chars)?.into_bytes(),
        ));
        kerning_modules.push(kerning.clone());
        glyph_count.push(chars.len());
        for size in &atlas.sizes {
            let name = module(face, size.size);
            let rust = size_module(spec, face, file, size, &name, &kerning)?;
            files.push((format!("{name}.rs"), rust.into_bytes()));
            files.push((format!("{name}.coverage"), size.coverage.clone()));
            statics.push((
                name.clone(),
                name.to_uppercase(),
                face.style.clone(),
                size.size,
            ));
            coverage_bytes = coverage_bytes.saturating_add(size.coverage.len());
            let _ = write!(
                atlas_entries,
                "\n[[atlas]]\nstatic = {}\nmodule = {}\nfont = {}\nsize = {}\nglyphs = {}\n\
                 kerning-pairs = {}\ncoverage-bytes = {}\ncoverage-sha256 = {}\n",
                toml_string(&name.to_uppercase()),
                toml_string(&name),
                toml_string(&file.path),
                size.size,
                size.glyphs.len(),
                atlas.kerning.len(),
                size.coverage.len(),
                toml_string(&crate::spec::sha256_hex(&size.coverage)),
            );
            if face.ranges.is_some() {
                let _ = writeln!(atlas_entries, "ranges = [{}]", show_ranges(ranges));
            }
        }
    }
    files.push((
        "mod.rs".into(),
        mod_rs(spec, &fonts, &statics, &kerning_modules).into_bytes(),
    ));
    files.push((
        "manifest.toml".into(),
        manifest(spec, faces, &atlas_entries).into_bytes(),
    ));
    files.sort_by(|a, b| a.0.cmp(&b.0));

    let mut summary = format!("glyph-atlas: PASS - {} atlases:", statics.len());
    for ((face, file, atlas), count) in faces.iter().zip(&glyph_count) {
        let sizes: Vec<String> = atlas
            .sizes
            .iter()
            .map(|size| size.size.to_string())
            .collect();
        let _ = write!(
            summary,
            " {} {} at {} px from {}, {count} characters, {} kerned pairs;",
            face.name,
            face.style,
            sizes.join(", "),
            file.path,
            atlas.kerning.len()
        );
    }
    let _ = write!(summary, " {coverage_bytes} bytes of coverage");
    Ok(Atlases { files, summary })
}

/// A set's ranges, as TOML: `[0x20, 0x7E], [0xA0, 0xAC]`.
fn show_ranges(ranges: &[(char, char)]) -> String {
    let ranges: Vec<String> = ranges
        .iter()
        .map(|(first, last)| format!("[0x{:02X}, 0x{:02X}]", u32::from(*first), u32::from(*last)))
        .collect();
    ranges.join(", ")
}

/// A face's kerning, shared by every size of it, as a Rust module: its
/// characters, its units per em and its kerned pairs in font units.
fn kerning_rs(
    spec: &Spec,
    face: &Face,
    file: &PinnedFile,
    atlas: &FaceAtlas,
    chars: &[char],
) -> Result<String, Error> {
    let mut text = header("//", spec, &[(face, file)]);
    let _ = write!(
        text,
        "//\n// The {style} face's pair kerning, in font units, which every size of it shares: an atlas\n\
         // scales an adjustment to 1/64 pixel at its own size when it is looked up, as the tool scales\n\
         // every metric, rounding half away from zero.\n\n\
         use crate::{{KernPair, index_of_char}};\n\n\
         /// The face's characters, in increasing order: every size's glyphs are these, in this order.\n\
         pub(crate) static CHARS: [char; {count}] = [",
        style = face.style,
        count = chars.len(),
    );
    for (index, ch) in chars.iter().enumerate() {
        if index % 12 == 0 {
            text.push_str("\n    ");
        } else {
            text.push(' ');
        }
        let _ = write!(text, "{},", char_literal(*ch));
    }
    let _ = write!(
        text,
        "\n];\n\n/// The font's units per em.\npub(crate) const UPEM: u16 = {upem};\n\n\
         /// A kerned pair, and the adjustment to the pen between them in font units.\n\
         const fn k(left: char, right: char, units: i16) -> KernPair {{\n    \
         KernPair::new(index_of_char(&CHARS, left), index_of_char(&CHARS, right), units)\n}}\n\n\
         pub(crate) static KERNING: [KernPair; {pairs}] = [\n",
        upem = atlas.upem,
        pairs = atlas.kerning.len(),
    );
    for pair in &atlas.kerning {
        let _ = writeln!(
            text,
            "    k({}, {}, {}),",
            char_literal(pair.left),
            char_literal(pair.right),
            pair.units
        );
    }
    text.push_str("];\n");
    if text.is_ascii() {
        Ok(text)
    } else {
        Err(Error::Spec(format!(
            "{}'s text must be ASCII, for the generated Rust: the family's name and copyright line",
            crate::SPEC_FILE
        )))
    }
}

/// One face at one size, as a Rust module.
fn size_module(
    spec: &Spec,
    face: &Face,
    file: &PinnedFile,
    atlas: &SizeAtlas,
    name: &str,
    kerning: &str,
) -> Result<String, Error> {
    let mut text = header("//", spec, &[(face, file)]);
    let _ = write!(
        text,
        "//\n// {size} pixels per em: {HOW}.\n\n\
         use super::{kerning}::{{CHARS, KERNING, UPEM}};\n\
         use crate::{{Atlas, Glyph, LineMetrics, is_whole, lay_out, same_chars}};\n\n\
         /// Every glyph's coverage, in the order of `GLYPHS`, each row by row from the top: one byte a\n\
         /// pixel, 0 for none and 255 for full.\n\
         const COVERAGE: &[u8; {bytes}] = include_bytes!(\"{name}.coverage\");\n\n\
         /// A glyph: its character; its advance, bearing x and bearing y in 1/64 pixel; and its ink box's\n\
         /// left and top from the pen on the baseline, its width and height, in pixels. Its pixels are the\n\
         /// next width * height bytes of `COVERAGE`, in the order of `GLYPHS`: `lay_out` gives them.\n\
         #[allow(clippy::too_many_arguments, reason = \"one row a glyph keeps the generated table readable\")]\n\
         const fn g(\n    ch: char,\n    advance: i32,\n    bearing_x: i32,\n    bearing_y: i32,\n    left: i16,\n    top: i16,\n    \
         width: u16,\n    height: u16,\n) -> Glyph {{\n    \
         Glyph {{ ch, advance, bearing_x, bearing_y, left, top, width, height, coverage: &[] }}\n}}\n\n\
         static GLYPHS: [Glyph; {glyphs}] = lay_out(COVERAGE, [\n",
        size = atlas.size,
        bytes = atlas.coverage.len(),
        glyphs = atlas.glyphs.len(),
        kerning = kerning,
    );
    for glyph in &atlas.glyphs {
        let _ = writeln!(
            text,
            "    g({}, {}, {}, {}, {}, {}, {}, {}),",
            char_literal(glyph.ch),
            glyph.advance,
            glyph.bearing_x,
            glyph.bearing_y,
            glyph.left,
            glyph.top,
            glyph.width,
            glyph.height
        );
    }
    text.push_str("]);\n");
    let [ascent, descent, line_gap] = atlas.line;
    let _ = write!(
        text,
        "\n/// The {style} face at {size} pixels per em.\n\
         pub static {upper}: Atlas = Atlas::new({size}, LineMetrics::new({ascent}, {descent}, {line_gap}), &GLYPHS, &KERNING, UPEM);\n\n\
         // Checked when this module compiles: both tables in the order the lookups search them in, no\n\
         // character twice; the glyphs exactly the face's characters, in order; every glyph's pixels\n\
         // exactly its width times its height, the glyphs taking all of COVERAGE; every kerned pair\n\
         // naming two glyphs, and none 0. The values - every pixel, metric and adjustment - are checked\n\
         // by `make atlases-check`, which makes the atlases again and compares them byte for byte.\n\
         const _: () = assert!(same_chars(&GLYPHS, &CHARS) && is_whole(&GLYPHS, &KERNING, COVERAGE.len()));\n",
        style = face.style,
        size = atlas.size,
        upper = name.to_uppercase(),
    );
    if text.is_ascii() {
        Ok(text)
    } else {
        Err(Error::Spec(format!(
            "{}'s text must be ASCII, for the generated Rust: the family's name and copyright line",
            crate::SPEC_FILE
        )))
    }
}

/// `mod.rs`: every atlas module, the atlases' statics and the notice.
fn mod_rs(
    spec: &Spec,
    fonts: &[(&Face, &PinnedFile)],
    statics: &[(String, String, String, u16)],
    kerning_modules: &[String],
) -> String {
    let mut text = header("//", spec, fonts);
    text.push('\n');
    let mut modules: Vec<&str> = statics
        .iter()
        .map(|(module, _, _, _)| module.as_str())
        .chain(kerning_modules.iter().map(String::as_str))
        .collect();
    modules.sort_unstable();
    for module in modules {
        let _ = writeln!(text, "mod {module};");
    }
    text.push('\n');
    for (module, upper, _, _) in statics {
        let _ = writeln!(text, "pub use {module}::{upper};");
    }
    let names: Vec<String> = statics
        .iter()
        .map(|(_, upper, _, _)| format!("&{upper}"))
        .collect();
    let family = &spec.family;
    let _ = write!(
        text,
        "\n/// Every atlas: each face in the order {} lists them, at each of its sizes, smallest\n\
         /// first.\n\
         pub static ATLASES: [&crate::Atlas; {count}] = [{names}];\n\n\
         /// The notice every copy of the atlases carries: the font's copyright line, and its licence\n\
         /// ({licence}; the licence's text is {licence_file} in this crate's folder).\n\
         pub const NOTICE: &str = {notice};\n",
        crate::SPEC_FILE,
        count = statics.len(),
        names = names.join(", "),
        licence = family.licence,
        licence_file = family.licence_file,
        notice = rust_string(&notice(spec)),
    );
    text
}

/// `manifest.toml`: what the atlases were made from and of, for each
/// image's SBOM (tools/image-sbom) and for checking text against the set.
fn manifest(spec: &Spec, faces: &[(&Face, &PinnedFile, FaceAtlas)], atlas_entries: &str) -> String {
    let family = &spec.family;
    let mut text = header(
        "#",
        spec,
        &faces
            .iter()
            .map(|(face, file, _)| (*face, *file))
            .collect::<Vec<_>>(),
    );
    let _ = write!(
        text,
        "#\n# What the atlases in this folder were made from and hold: tools/image-sbom names the font\n\
         # in every image's SBOM from it, and Screen Compiler can check text against the character set.\n\n\
         crate = {}\nlicence = {}\nnotice = {}\ncopyright = {}\nrasteriser = {}\nmade = {}\n",
        toml_string(&spec.crate_name),
        toml_string(&family.licence),
        toml_string(&family.licence_file),
        toml_string(&family.copyright),
        toml_string(RASTERISER),
        toml_string(HOW),
    );
    // Each font file once, as tools/image-sbom names each in an image's
    // SBOM: the display face is made from the Bold face's file.
    for (index, (face, file, _)) in faces.iter().enumerate() {
        if faces
            .iter()
            .take(index)
            .any(|(_, earlier, _)| earlier.path == file.path)
        {
            continue;
        }
        let _ = write!(
            text,
            "\n[[font]]\nfamily = {}\nversion = {}\nstyle = {}\nfile = {}\nsha256 = {}\nsource = {}\ndecision = {}\n",
            toml_string(&family.name),
            toml_string(&file.version),
            toml_string(&face.style),
            toml_string(&file.path),
            toml_string(&file.sha256),
            toml_string(&format!(
                "{}/blob/{}/{}",
                family.repository, family.commit, file.upstream
            )),
            toml_string(&family.decision),
        );
    }
    text.push_str(atlas_entries);
    let _ = write!(
        text,
        "\n[characters]\ncount = {}\nranges = [{}]\n",
        spec.chars.len(),
        show_ranges(&spec.ranges)
    );
    for (ch, of) in &spec.aliases {
        let _ = write!(
            text,
            "\n[[characters.alias]]\nchar = 0x{:02X}\nglyph-of = 0x{:02X}\n",
            u32::from(*ch),
            u32::from(*of)
        );
    }
    text
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn literals_are_ascii_and_escaped() {
        assert_eq!(char_literal('A'), "'A'");
        assert_eq!(char_literal('\''), "'\\''");
        assert_eq!(char_literal('\\'), "'\\\\'");
        assert_eq!(char_literal('"'), "'\"'");
        assert_eq!(char_literal('\u{A0}'), "'\\u{a0}'");
        assert_eq!(char_literal('\u{FF}'), "'\\u{ff}'");
        assert_eq!(
            rust_string("a \"b\" \\ \u{e9}"),
            "\"a \\\"b\\\" \\\\ \\u{e9}\""
        );
        assert_eq!(
            toml_string("a \"b\" \\ \u{e9} \u{1F600}"),
            "\"a \\\"b\\\" \\\\ \\u00E9 \\U0001F600\""
        );
    }

    #[test]
    fn licences_are_named() {
        assert!(licence_name("OFL-1.1").contains("SIL Open Font License, Version 1.1"));
        assert_eq!(licence_name("MIT"), "MIT");
    }
}
